            .{ .binding = 0, .texture_view = z3d.g_default_tex_view.? },
            .{ .binding = 1, .sampler = z3d.g_diffuse_sampler.? },
            .{ .binding = 2, .buffer = z3d.g_uv_unbounded_uniform.?, .offset = 0, .size = 4 * @sizeOf(f32) },
