            .layout = z3d.g_tex_bind_group_layout.?,
            .entry_count = def_entries.len,
            .entries = &def_entries,
        });
    }

    // Independent glass atlas. It deliberately uses unbounded sampling: every UV
    // resolves to this one texel, so glass can never fall back into, overlap, or
    // transfer opacity through the opaque model atlas.
    z3d.g_glass_aux_tex = device.createTexture(&.{
        .label = wgpu.StringView.fromSlice("r3d_glass_aux"),
        .size = .{ .width = 1, .height = 1, .depth_or_array_layers = 1 },
        .mip_level_count = 1,
        .sample_count = 1,
        .dimension = .@"2d",
        .format = .rgba8_unorm,
        .usage = wgpu.TextureUsages.texture_binding | wgpu.TextureUsages.copy_dst,
    });
    if (z3d.g_glass_aux_tex) |glass_tex| {
        const queue = core.getQueue();
        if (queue) |q| {
            q.writeTexture(
                &.{ .texture = glass_tex, .mip_level = 0, .origin = .{}, .aspect = .all },
                @ptrCast(&model_paint.GLASS_AUX_TEXEL),
                model_paint.GLASS_AUX_TEXEL.len,
                &.{ .offset = 0, .bytes_per_row = 4, .rows_per_image = 1 },
                &.{ .width = 1, .height = 1, .depth_or_array_layers = 1 },
            );
        }
        z3d.g_glass_aux_tex_view = glass_tex.createView(&.{
            .format = .rgba8_unorm,
            .dimension = .@"2d",
            .base_mip_level = 0,
            .mip_level_count = 1,
            .base_array_layer = 0,
            .array_layer_count = 1,
            .aspect = .all,
        });
    }
    if (z3d.g_glass_aux_tex_view != null and z3d.g_diffuse_sampler != null and z3d.g_uv_unbounded_uniform != null) {
        const glass_entries = [_]wgpu.BindGroupEntry{
            .{ .binding = 0, .texture_view = z3d.g_glass_aux_tex_view.? },
            .{ .binding = 1, .sampler = z3d.g_diffuse_sampler.? },
            .{ .binding = 2, .buffer = z3d.g_uv_unbounded_uniform.?, .offset = 0, .size = 4 * @sizeOf(f32) },
        };
        z3d.g_glass_aux_tex_bind_group = device.createBindGroup(&.{
            .layout = z3d.g_tex_bind_group_layout.?,
            .entry_count = glass_entries.len,
            .entries = &glass_entries,
        });
